import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from google.cloud import monitoring_v3


def query_gcp_metric_data(
    project_id: str,
    metric_type: str,
    start_time: datetime,
    end_time: datetime,
    resource_type: Optional[str] = None,
    resource_labels: Optional[Dict[str, str]] = None,
    metric_labels: Optional[Dict[str, str]] = None,
    alignment_period_seconds: int = 300,
    per_series_aligner: str = "ALIGN_MEAN",
    cross_series_reducer: Optional[str] = None,
    group_by_fields: Optional[List[str]] = None,
    page_size: int = 1000,
) -> List[Dict[str, Any]]:
    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    filter_parts = [f'metric.type = "{metric_type}"']

    if resource_type:
        filter_parts.append(f'resource.type = "{resource_type}"')

    for key, value in (resource_labels or {}).items():
        filter_parts.append(f'resource.labels.{key} = "{value}"')

    for key, value in (metric_labels or {}).items():
        filter_parts.append(f'metric.labels.{key} = "{value}"')

    filter_str = " AND ".join(filter_parts)

    interval = monitoring_v3.TimeInterval(
        {
            "start_time": start_time,
            "end_time": end_time,
        }
    )

    aggregation = monitoring_v3.Aggregation(
        {
            "alignment_period": {"seconds": alignment_period_seconds},
            "per_series_aligner": getattr(
                monitoring_v3.Aggregation.Aligner, per_series_aligner
            ),
        }
    )

    if cross_series_reducer:
        aggregation.cross_series_reducer = getattr(
            monitoring_v3.Aggregation.Reducer, cross_series_reducer
        )
        aggregation.group_by_fields.extend(group_by_fields or [])

    results = client.list_time_series(
        request={
            "name": project_name,
            "filter": filter_str,
            "interval": interval,
            "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
            "aggregation": aggregation,
            "page_size": page_size,
        }
    )

    output: List[Dict[str, Any]] = []
    for series in results:
        points = []
        for point in series.points:
            value = None
            typed_value = point.value
            kind = typed_value.WhichOneof("value")
            if kind == "double_value":
                value = typed_value.double_value
            elif kind == "int64_value":
                value = typed_value.int64_value
            elif kind == "bool_value":
                value = typed_value.bool_value
            elif kind == "string_value":
                value = typed_value.string_value
            elif kind == "distribution_value":
                value = {
                    "count": typed_value.distribution_value.count,
                    "mean": typed_value.distribution_value.mean,
                }

            points.append(
                {
                    "interval_start": point.interval.start_time.isoformat(),
                    "interval_end": point.interval.end_time.isoformat(),
                    "value": value,
                }
            )

        output.append(
            {
                "metric_type": series.metric.type,
                "metric_labels": dict(series.metric.labels),
                "resource_type": series.resource.type,
                "resource_labels": dict(series.resource.labels),
                "points": points,
            }
        )

    return output


if __name__ == "__main__":
    project_id = os.environ["GCP_PROJECT_ID"]
    metric_type = os.environ["GCP_METRIC_TYPE"]
    resource_type = os.getenv("GCP_RESOURCE_TYPE")
    instance_id = os.getenv("GCP_INSTANCE_ID")

    end = datetime.now(timezone.utc)
    start = end - timedelta(hours=1)

    data = query_gcp_metric_data(
        project_id=project_id,
        metric_type=metric_type,
        start_time=start,
        end_time=end,
        resource_type=resource_type,
        resource_labels={"instance_id": instance_id} if instance_id else None,
        alignment_period_seconds=300,
        per_series_aligner="ALIGN_MEAN",
    )

    print(data)
